MASK_30 = [True, False, True, True, False, False, True, False, True, False,
           False, True, True, False, False, True, False, True, True, False,
           True, False, False, True, True, False, False, True, False, True]
MASK_20 = [True, False, True, False, False, True, True, False, True, False,
           False, True, True, False, False, True, True, False, False, True]

def is_question_true(batch_index, topic_index):
    if batch_index < 16:
        offset = (batch_index * 7 + 3) % 30
        return MASK_30[(topic_index + offset) % 30]
    else:
        offset = (batch_index * 3 + 1) % 20
        return MASK_20[(topic_index + offset) % 20]

def escape_kt(text):
    return text.replace('\\', '\\\\').replace('"', '\\"').replace('$', '\\$')

